input.command:
cd /tmp && perl -e '
my @cases = ("http://a:\t8", "http://a:\n8", "http://a:\x0b8", "http://a:\x0c8", "http://a:\r8", "http://a:8\t", "http://a: ", "http://a:\t", "http://a:\x008", "http://a:8\x000");
for my $c (@cases) {
  (my $show = $c) =~ s/([^\x20-\x7e])/sprintf("\\x%02x",ord($1))/ge;
  print "=== [$show]\n";
  my $pid = open(my $fh, "-|");
  if ($pid == 0) { open(STDERR, ">&", STDOUT); exec("/workspace/dataset/test5_executable", $c); exit 127; }
  my @l = <$fh>; close($fh); my $ec = $? >> 8;
  for my $i (0..$#l) { my $x = $l[$i]; $x =~ s/([^\x20-\x7e])/sprintf("\\x%02x",ord($1))/ge; printf("  %d: [%s]\n", $i+1, $x); }
  print "  exit=$ec nlines=".scalar(@l)."\n";
}'

cd /tmp && perl -e '
srand(1234);
my $bad = 0;
for my $i (1..400) {
  my $len = int(rand(12));
  my $p = "";
  my @pool = (0x20..0x7e);
  push @pool, (0x09,0x0a,0x0b,0x0c,0x0d,0x80,0xff,0xc2,0xa0);
  for (1..$len) { $p .= chr($pool[int(rand(scalar @pool))]); }
  my $u = "http://a:".$p;
  my $pid = open(my $fh, "-|");
  if ($pid == 0) { open(STDERR, ">&", STDOUT); exec("/workspace/dataset/test5_executable", $u); exit 127; }
  my @l = <$fh>; close($fh); my $ec = $? >> 8; my $sig = $? & 127;
  if ($ec != 0 || $sig != 0 || scalar(@l) != 5) {
    (my $s = $u) =~ s/([^\x20-\x7e])/sprintf("\\x%02x",ord($1))/ge;
    print "ANOMALY [$s] exit=$ec sig=$sig nlines=".scalar(@l)."\n";
    for my $x (@l) { $x =~ s/([^\x20-\x7e])/sprintf("\\x%02x",ord($1))/ge; print "   [$x]\n"; }
    $bad++;
  }
}
print "anomalies=$bad of 400\n";'
echo "=== huge port string 1MB digits ==="
BIG=$(perl -e 'print "1"x1000000'); /workspace/dataset/test5_executable "http://a:$BIG" >/tmp/o.txt 2>/tmp/e.txt; echo "exit=$?"; sed -n '3p' /tmp/o.txt | cat -A; echo "stderr=[$(cat /tmp/e.txt)]"; wc -l < /tmp/o.txt
